#include <float.h>
#include <math.h>
#include <stdbool.h>
#include <stdio.h>

static bool calculate(double left, char op, double right, double *result)
{
    if (result == NULL || !isfinite(left) || !isfinite(right)) {
        return false;
    }

    double value = 0.0;
    switch (op) {
    case '+':
        value = left + right;
        break;
    case '-':
        value = left - right;
        break;
    case '*':
        value = left * right;
        break;
    case '/':
        if (right == 0.0) return false;
        value = left / right;
        break;
    default:
        return false;
    }

    if (!isfinite(value)) return false;
    *result = value;
    return true;
}

static bool check_result(const char *label, double left, char op,
                         double right, double expected)
{
    double actual = 0.0;
    if (!calculate(left, op, right, &actual) || actual != expected) {
        printf("FAIL: %s\n", label);
        return false;
    }
    printf("PASS: %s = %.6g\n", label, actual);
    return true;
}

int main(void)
{
    double result = 0.0;

    if (!check_result("addition", 8.0, '+', 3.0, 11.0)) return 1;
    if (!check_result("subtraction", 8.0, '-', 3.0, 5.0)) return 1;
    if (!check_result("multiplication", 8.0, '*', 3.0, 24.0)) return 1;
    if (!check_result("division", 8.0, '/', 2.0, 4.0)) return 1;

    if (calculate(8.0, '/', 0.0, &result)) {
        puts("FAIL: division by zero was accepted");
        return 1;
    }
    if (calculate(8.0, '%', 3.0, &result)) {
        puts("FAIL: unsupported operator was accepted");
