        return 1;
    }

    puts("All arithmetic engine tests passed.");
    return 0;
}

#include <ctype.h>
#include <errno.h>
#include <math.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INPUT_SIZE 256U

static const char *skip_spaces(const char *text)
{
    while (isspace((unsigned char)*text)) {
        ++text;
    }
    return text;
}

static bool parse_number(const char **cursor, double *value)
{
    char *end = NULL;
    errno = 0;
    double parsed = strtod(*cursor, &end);

    if (end == *cursor || errno == ERANGE || !isfinite(parsed)) {
        return false;
    }

    *cursor = end;
    *value = parsed;
    return true;
}

static bool parse_expression(const char *line, double *left,
                             char *op, double *right)
{
    const char *cursor = skip_spaces(line);

    if (!parse_number(&cursor, left)) return false;
    cursor = skip_spaces(cursor);

    if (*cursor != '+' && *cursor != '-' &&
        *cursor != '*' && *cursor != '/') {
        return false;
    }
    *op = *cursor;
    ++cursor;
    cursor = skip_spaces(cursor);

    if (!parse_number(&cursor, right)) return false;
    cursor = skip_spaces(cursor);

    return *cursor == '\0';
}

static bool calculate(double left, char op, double right, double *result)
{
    if (result == NULL || !isfinite(left) || !isfinite(right)) {
        return false;
    }

    double value = 0.0;
    switch (op) {
    case '+':
        value = left + right;
        break;
    case '-':
        value = left - right;
        break;
    case '*':
        value = left * right;
        break;
    case '/':
        if (right == 0.0) return false;
        value = left / right;
        break;
    default:
        return false;
    }

    if (!isfinite(value)) return false;
    *result = value;
    return true;
}

static bool is_quit_command(const char *line)
{
    const char *text = skip_spaces(line);
    return text[0] == 'q' && skip_spaces(text + 1)[0] == '\0';
}

static bool read_line(char buffer[INPUT_SIZE])
{
    if (fgets(buffer, (int)INPUT_SIZE, stdin) == NULL) {
        return false;
    }

    char *newline = strchr(buffer, '\n');
    if (newline != NULL) {
        *newline = '\0';
        return true;
    }

    if (!feof(stdin)) {
        int ch;
        while ((ch = getchar()) != '\n' && ch != EOF) {
            /* Discard the rest of an overlong input line. */
        }
        return false;
    }

    return true;
}

int main(void)
{
    char line[INPUT_SIZE];

    puts("CodeSaathi Calculator (+, -, *, /). Enter q to quit.");

    for (;;) {
        double left = 0.0;
        double right = 0.0;
        double result = 0.0;
        char op = '\0';

        fputs("> ", stdout);
        fflush(stdout);

        if (!read_line(line)) {
            if (feof(stdin)) break;
            puts("Input line too long; please try a shorter expression.");
            continue;
        }

        if (is_quit_command(line)) break;

        if (!parse_expression(line, &left, &op, &right)) {
            puts("Invalid expression. Use: number operator number");
            continue;
        }

        if (!calculate(left, op, right, &result)) {
            puts("Cannot calculate: check the divisor and numeric range.");
            continue;
        }

        printf("= %.10g\n", result);
    }

    puts("Goodbye.");
    return 0;
}
